    source(policy,segment);ensure(policy.kind==='growing-u95e5-caps','private 闥 eight exact original initial guides only')
    if(!Number.isFinite(progress)||progress<0||progress>1||!/^[A-Za-z0-9_:.-]+$/.test(clipId))throw new Error('Invalid 闥 frame/id')
